        if avg >= 85.0:
            grade = "A"
        elif avg >= 70.0:
            grade = "B"
        elif avg > 50.0:
            grade = "C"
        else:
            grade = "F"
    print(f"Average: {avg:.2f} | Attendance: {attendance}% | Status: {status} | Grade: {grade}")

