def sort_leaderboard(students):
    n = len(students)
    for i in range(n):
        for j in range(0, n - i - 1):
            s1, s2 = students[j], students[j + 1]
            swap = False
            if s1['score'] < s2['score']:
                swap = True
            elif s1['score'] == s2['score'] and s1['solved'] > s2['solved']:
                swap = True
            if swap:
                students[j], students[j + 1] = students[j + 1], students[j]

def calculate_median(scores):
    n = len(scores)
    if n == 0:
        return 0.0
    mid = n // 2
    if n % 2 == 1:
        return float(scores[mid])
    return (scores[mid] + scores[mid + 1]) / 2.0

def find_score_rank(students, target_score):
    low = 0
    high = len(students) - 1
    found_idx = -1
    while low <= high:
        mid = (low + high) // 2
        if students[mid]['score'] == target_score:
            found_idx = mid
            high = mid - 1
        elif students[mid]['score'] < target_score:
            high = mid
        else:
            low = mid + 1
    return found_idx + 1 if found_idx != -1 else -1

def print_top_performers(students, k):
    print("=== Top Performers ===")
    for i in range(k + 1):
        s = students[i]
        print(f"Rank {i+1}: {s['name']} (Score: {s['score']}, Solved: {s['solved']})")

