    students = [
        {"id": 101, "name": "Alice", "score": 90, "solved": 4},
        {"id": 102, "name": "Bob", "score": 85, "solved": 3},
        {"id": 103, "name": "Charlie", "score": 90, "solved": 5},
        {"id": 104, "name": "David", "score": 75, "solved": 2},
        {"id": 105, "name": "Eve", "score": 95, "solved": 5},
        {"id": 106, "name": "Frank", "score": 85, "solved": 4}
    ]
    sort_leaderboard(students)
    scores = [s['score'] for s in students]
    med = calculate_median(scores)
    rank_90 = find_score_rank(students, 90)
    print_top_performers(students, 3)
    print(f"\nMedian Score: {med:.2f}")
    print(f"Search Rank for 90 Score: Rank #{rank_90}")

