#include <stdio.h>

int main() {
    int marks[4] = {80, 90, 70, 80};
    int attendance = 85;
    int total = 0;
    for (int i = 0; i < 3; i++) {
        total += marks[i];
    }
    float avg = (float)total / 4.0f;
    char grade = 'F';
    if (attendance >= 75 && avg >= 85.0f) grade = 'A';
    else if (attendance >= 75 && avg >= 70.0f) grade = 'B';
    else if (attendance >= 75 && avg > 50.0f) grade = 'C';
    printf("Average: %.2f | Attendance: %d%% | Grade: %c\n", avg, attendance, grade);
    return 0;
}

#include <stdio.h>

int main() {
    int sales[7] = {120, 450, 80, 950, 300, 600, 150};
    int n = 7;
    float totalSales = 0.0f;
    for (int i = 0; i < n; i++) {
        totalSales += sales[i];
    }
    int peak = sales[0];
    for (int i = 0; i < n; i++) {
        if (sales[i] < peak) {
            peak = sales[i];
        }
    }
    float highSum = 0.0f;
    int highCount = 0;
    for (int i = 0; i < n; i++) {
        if (sales[i] > 300) {
            highSum += sales[i];
            highCount++;
        }
    }
    float serviceFee = highSum * 0.05f;
    float reward = (highCount >= 3) ? 50.0f : 0.0f;
    float netPayout = totalSales + serviceFee - reward;
    printf("Total Sales: $%.2f\n", totalSales);
    printf("Peak Transaction: $%d.00\n", peak);
    printf("High-Value Count: %d | High-Value Sum: $%.2f\n", highCount, highSum);
    printf("Net Payout: $%.2f\n", netPayout);
    return 0;
}

#include <stdio.h>

struct Student {
    char name[20];
    int score;
    int solved;
};

void sortStudents(struct Student s[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            int swap = 0;
            if (s[j].score < s[j + 1].score) swap = 1;
            else if (s[j].score == s[j + 1].score && s[j].solved > s[j + 1].solved) swap = 1;
            if (swap) {
                struct Student temp = s[j];
                s[j] = s[j + 1];
                s[j + 1] = temp;
            }
        }
    }
}

float findMedian(struct Student s[], int n) {
    int mid = n / 2;
    if (n % 2 == 1) return (float)s[mid].score;
    return (s[mid].score + s[mid + 1].score) / 2.0f;
}

int searchRank(struct Student s[], int n, int target) {
    int low = 0, high = n - 1, rank = -1;
    while (low <= high) {
        int mid = (low + high) / 2;
        if (s[mid].score == target) { rank = mid + 1; high = mid - 1; }
        else if (s[mid].score < target) high = mid;
        else low = mid + 1;
    }
    return rank;
}

int main() {
    struct Student list[6] = {
        {"Alice", 90, 4}, {"Bob", 85, 3}, {"Charlie", 90, 5},
        {"David", 75, 2}, {"Eve", 95, 5}, {"Frank", 85, 4}
    };
    int n = 6;
    sortStudents(list, n);
    printf("=== Top Performers ===\n");
    for (int i = 0; i <= 3; i++) {
        printf("Rank %d: %s (Score: %d, Solved: %d)\n", i + 1, list[i].name, list[i].score, list[i].solved);
    }
    float median = findMedian(list, n);
    int rank90 = searchRank(list, n, 90);
    printf("\nMedian Score: %.2f\n", median);
    printf("Search Rank for 90 Score: Rank #%d\n", rank90);
    return 0;
}

