#include <stdio.h>

struct Student {
    char name[20];
    int score;
    int solved;
};

void sortStudents(struct Student s[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            int swap = 0;
            if (s[j].score < s[j + 1].score) swap = 1;
            else if (s[j].score == s[j + 1].score && s[j].solved > s[j + 1].solved) swap = 1;
            if (swap) {
                struct Student temp = s[j];
                s[j] = s[j + 1];
                s[j + 1] = temp;
            }
        }
    }
}

float findMedian(struct Student s[], int n) {
    int mid = n / 2;
    if (n % 2 == 1) return (float)s[mid].score;
    return (s[mid].score + s[mid + 1].score) / 2.0f;
}

int searchRank(struct Student s[], int n, int target) {
    int low = 0, high = n - 1, rank = -1;
    while (low <= high) {
        int mid = (low + high) / 2;
        if (s[mid].score == target) { rank = mid + 1; high = mid - 1; }
        else if (s[mid].score < target) high = mid;
        else low = mid + 1;
    }
    return rank;
}

