    struct Student list[6] = {
        {"Alice", 90, 4}, {"Bob", 85, 3}, {"Charlie", 90, 5},
        {"David", 75, 2}, {"Eve", 95, 5}, {"Frank", 85, 4}
    };
    int n = 6;
    sortStudents(list, n);
    printf("=== Top Performers ===\n");
    for (int i = 0; i <= 3; i++) {
        printf("Rank %d: %s (Score: %d, Solved: %d)\n", i + 1, list[i].name, list[i].score, list[i].solved);
    }
    float median = findMedian(list, n);
    int rank90 = searchRank(list, n, 90);
    printf("\nMedian Score: %.2f\n", median);
    printf("Search Rank for 90 Score: Rank #%d\n", rank90);
    return 0;
}

