def calculate_median(scores):
    n = len(scores)
    if n == 0:
        return 0.0
    mid = n // 2
    if n % 2 == 1:
        return float(scores[mid])
    return (scores[mid - 1] + scores[mid]) / 2.0

def find_score_rank(students, target_score):
    low = 0
    high = len(students) - 1
    found_idx = -1
    while low <= high:
        mid = (low + high) // 2
        if students[mid]['score'] == target_score:
            found_idx = mid
            high = mid - 1
        elif students[mid]['score'] < target_score:
            high = mid - 1
        else:
            low = mid + 1
    return found_idx + 1 if found_idx != -1 else -1

